print(has_duplicates([1, 2, 3, 4, 4]))  # Returns: True

def product_of_non_repeated_elements(arr):
    # Create a dictionary to store the frequency of each element
    freq_dict = {}
    for num in arr:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Initialize the product
    product = 1

    # Iterate over the dictionary
    for num, freq in freq_dict.items():
        # If the frequency is 1, multiply the product by the number
        if freq == 1:
            product *= num

    return product

