def can_rearrange(s):
    # Create a dictionary to store the frequency of each character
    char_freq = {}
    for char in s:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # Initialize a variable to store the number of characters with odd frequency
    odd_count = 0

    # Iterate over the frequency of each character
    for freq in char_freq.values():
        # If the frequency is odd, increment the odd count
        if freq % 2 != 0:
            odd_count += 1

    # If there are more than one characters with odd frequency, it's not possible to rearrange
    if odd_count > 1:
        return False
    else:
        return True

def filter_even_numbers(numbers):
    return list(filter(lambda x: x % 2 == 0, numbers))

