def sum_of_repeated_elements(arr):
    # Create a dictionary to store the frequency of each element
    freq_dict = {}
    for num in arr:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Initialize sum of repeated elements to 0
    repeated_sum = 0

    # Iterate over the dictionary and add the product of each number and its frequency to the sum
    for num, freq in freq_dict.items():
        if freq > 1:
            repeated_sum += num * freq

    return repeated_sum

def gcd_of_array(arr):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    result = arr[0]
    for num in arr[1:]:
        result = gcd(result, num)
    return result

# Test the function
